// Checks lib/floorPlans.json (generated by scripts/make-floor-plans.py). Run: npm test
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { existsSync, readFileSync } from 'node:fs';

const data = JSON.parse(readFileSync('lib/floorPlans.json', 'utf8'));

test('one outline per apartment: 14 on floors 1-4, 7 on floor 5', () => {
  const floors = data.r1;
  assert.deepEqual(floors.map((f: any) => [f.level, f.shapes.length]), [[1, 14], [2, 14], [3, 14], [4, 14], [5, 7]]);
  for (const f of floors) {
    const codes = f.shapes.map((s: any) => s.unit);
    assert.equal(new Set(codes).size, codes.length, `floor ${f.level} duplicate`);
    for (const c of codes) assert.ok(existsSync(`public/riverina/pdf/${c}.pdf`), `no sheet for ${c}`);
  }
});

test('outlines are polygons inside the plan image', () => {
  for (const f of data.r1) {
    assert.ok(existsSync('public' + f.image), f.image);
    for (const s of f.shapes) {
      assert.ok(s.pts.length >= 4, `${s.unit} has ${s.pts.length} corners`);
      for (const [x, y] of s.pts) assert.ok(x >= 0 && x <= 1 && y >= 0 && y <= 1, `${s.unit} point ${x},${y}`);
    }
  }
});

test('every apartment has a plan crop', () => {
  for (const f of data.r1) for (const s of f.shapes) assert.ok(existsSync(`public/riverina/units/${s.unit}.webp`), s.unit);
});
